    if (oldViewProps == nullptr
          ? newViewProps.onEndEditingWorklet.isProvided()
          : !newViewProps.onEndEditingWorklet.hasSameValue(oldViewProps->onEndEditingWorklet)) {
      swiftPart.setOnEndEditingWorklet(newViewProps.onEndEditingWorklet.get());
    }
    // onKeyPressWorklet: number
    if (oldViewProps == nullptr
          ? newViewProps.onKeyPressWorklet.isProvided()
          : !newViewProps.onKeyPressWorklet.hasSameValue(oldViewProps->onKeyPressWorklet)) {
      swiftPart.setOnKeyPressWorklet(newViewProps.onKeyPressWorklet.get());
    }
    // onChangeText: optional
    if (oldViewProps == nullptr
          ? newViewProps.onChangeText.isProvided()
          : !newViewProps.onChangeText.hasSameValue(oldViewProps->onChangeText)) {
      swiftPart.setOnChangeText(newViewProps.onChangeText.get());
    }
    // onChangeMask: optional
    if (oldViewProps == nullptr
          ? newViewProps.onChangeMask.isProvided()
          : !newViewProps.onChangeMask.hasSameValue(oldViewProps->onChangeMask)) {
      swiftPart.setOnChangeMask(newViewProps.onChangeMask.get());
    }
    // onChangeValue: optional
    if (oldViewProps == nullptr
          ? newViewProps.onChangeValue.isProvided()
          : !newViewProps.onChangeValue.hasSameValue(oldViewProps->onChangeValue)) {
      swiftPart.setOnChangeValue(newViewProps.onChangeValue.get());
    }
    // onFocusChange: optional
    if (oldViewProps == nullptr
          ? newViewProps.onFocusChange.isProvided()
          : !newViewProps.onFocusChange.hasSameValue(oldViewProps->onFocusChange)) {
      swiftPart.setOnFocusChange(newViewProps.onFocusChange.get());
    }
    // onSubmitEditing: optional
    if (oldViewProps == nullptr
          ? newViewProps.onSubmitEditing.isProvided()
          : !newViewProps.onSubmitEditing.hasSameValue(oldViewProps->onSubmitEditing)) {
      swiftPart.setOnSubmitEditing(newViewProps.onSubmitEditing.get());
    }
    // onEndEditing: optional
    if (oldViewProps == nullptr
          ? newViewProps.onEndEditing.isProvided()
          : !newViewProps.onEndEditing.hasSameValue(oldViewProps->onEndEditing)) {
      swiftPart.setOnEndEditing(newViewProps.onEndEditing.get());
    }
    // onSelectionChange: optional
    if (oldViewProps == nullptr
          ? newViewProps.onSelectionChange.isProvided()
          : !newViewProps.onSelectionChange.hasSameValue(oldViewProps->onSelectionChange)) {
      swiftPart.setOnSelectionChange(newViewProps.onSelectionChange.get());
    }
    // onKeyPress: optional
    if (oldViewProps == nullptr
          ? newViewProps.onKeyPress.isProvided()
          : !newViewProps.onKeyPress.hasSameValue(oldViewProps->onKeyPress)) {
      swiftPart.setOnKeyPress(newViewProps.onKeyPress.get());
    }
    // onSizeChange: optional
    if (oldViewProps == nullptr
          ? newViewProps.onSizeChange.isProvided()
          : !newViewProps.onSizeChange.hasSameValue(oldViewProps->onSizeChange)) {
      swiftPart.setOnSizeChange(newViewProps.onSizeChange.get());
    }

    // Update hybridRef if it changed
    if (oldViewProps == nullptr
          ? newViewProps.hybridRef.isProvided()
          : !newViewProps.hybridRef.hasSameValue(oldViewProps->hybridRef)) {
      // hybridRef changed - call it with new this
      const auto& maybeFunc = newViewProps.hybridRef.get();
      if (maybeFunc.has_value()) {
        maybeFunc.value()(_hybridView);
      }
    }

    swiftPart.afterUpdate();
  }

  // 3. Continue in base class
  [super updateProps:props oldProps:oldProps];
}

+ (BOOL)shouldBeRecycled {
  return NitroInput::NitroInputAutolinking::isNitroInputViewRecyclable();
}

- (void)prepareForRecycle {
  [self notifyOnDropView];
  [super prepareForRecycle];
  NitroInput::HybridNitroInputViewSpec_cxx& swiftPart = _hybridView->getSwiftPart();
  swiftPart.maybePrepareForRecycle();
}

#ifdef ENABLE_RCT_COMPONENT_VIEW_INVALIDATE
- (void)invalidate {
  [self notifyOnDropView];
  [super invalidate];
}
#endif

@end
